package org.apache.commons.math.linear;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class BigMatrixImpl_operate_TriageGen1Test {

    @Test
    public void testOperate_Success() {
        // Create a 2x3 matrix:
        // [ 1, 2, 3 ]
        // [ 4, 5, 6 ]
        BigDecimal[][] data = {
            {new BigDecimal("1"), new BigDecimal("2"), new BigDecimal("3")},
            {new BigDecimal("4"), new BigDecimal("5"), new BigDecimal("6")}
        };
        BigMatrixImpl matrix = new BigMatrixImpl(data);

        // Vector v (length 3)
        BigDecimal[] v = {
            new BigDecimal("1"),
            new BigDecimal("2"),
            new BigDecimal("3")
        };

        // Expected calculation:
        // Row 0: (1*1) + (2*2) + (3*3) = 1 + 4 + 9 = 14
        // Row 1: (4*1) + (5*2) + (6*3) = 4 + 10 + 18 = 32
        BigDecimal[] expected = {
            new BigDecimal("14"),
            new BigDecimal("32")
        };

        BigDecimal[] result = matrix.operate(v);

        Assert.assertArrayEquals(expected, result);
    }

    @Test
    public void testOperate_WrongVectorLength_ThrowsException() {
        // Create a 2x2 matrix
        BigMatrixImpl matrix = new BigMatrixImpl(2, 2);

        // Vector v is length 3, but matrix expects length 2
        BigDecimal[] v = {
            BigDecimal.ONE,
            BigDecimal.ONE,
            BigDecimal.ONE
        };

        try {
            matrix.operate(v);
            Assert.fail("Expected IllegalArgumentException to be thrown");
        } catch (IllegalArgumentException e) {
            Assert.assertEquals("vector has wrong length", e.getMessage());
        }
    }

    @Test
    public void testOperate_SingleElementMatrix() {
        // 1x1 Matrix [5]
        BigDecimal[][] data = {{new BigDecimal("5")}};
        BigMatrixImpl matrix = new BigMatrixImpl(data);

        BigDecimal[] v = {new BigDecimal("2")};
        BigDecimal[] expected = {new BigDecimal("10")};

        BigDecimal[] result = matrix.operate(v);
        Assert.assertArrayEquals(expected, result);
    }

    @Test
    public void testOperate_WithZeroValues() {
        // 2x2 Matrix
        // [ 0, 5 ]
        // [ 2, 0 ]
        BigDecimal[][] data = {
            {BigDecimal.ZERO, new BigDecimal("5")},
            {new BigDecimal("2"), BigDecimal.ZERO}
        };
        BigMatrixImpl matrix = new BigMatrixImpl(data);

        // Vector [1, 1]
        BigDecimal[] v = {BigDecimal.ONE, BigDecimal.ONE};

        // Expected: [5, 2]
        BigDecimal[] expected = {new BigDecimal("5"), new BigDecimal("2")};

        BigDecimal[] result = matrix.operate(v);
        Assert.assertArrayEquals(expected, result);
    }

    @Test
    public void testOperate_NegativeValues() {
        // 1x2 Matrix [-1, -2]
        BigDecimal[][] data = {{new BigDecimal("-1"), new BigDecimal("-2")}};
        BigMatrixImpl matrix = new BigMatrixImpl(data);

        // Vector [-3, 4]
        BigDecimal[] v = {new BigDecimal("-3"), new BigDecimal("4")};

        // Expected: (-1*-3) + (-2*4) = 3 - 8 = -5
        BigDecimal[] expected = {new BigDecimal("-5")};

        BigDecimal[] result = matrix.operate(v);
        Assert.assertArrayEquals(expected, result);
    }
}
